def sum_to(n):
    total = 0
    for k in range(1, n + 1):
        total = total + k
    return total

def total_pnl(pnls):
    total = 0
    for p in pnls:
        total = total + p
    return total

def up_days(returns):
    count = 0
    for r in returns:
        if r > 0:
            count = count + 1
    return count

